def translate(s):
    prot=""
    for i in range(0,len(s)-2,3):
        prot+=codon[s[i:i+3]]
    return prot

def orfs(s, strand):
    res=[]
    for frame in range(3):
        prot=translate(s[frame:])
        # find stretches between stops
        aa_pos=0
        start=0
        p=frame
        cur_start=None
        for j,aa in enumerate(prot):
            if aa=='M' and cur_start is None:
                cur_start=j
            if aa=='*':
                if cur_start is not None:
                    res.append((cur_start*3+frame, j*3+frame, j-cur_start, strand, frame))
                cur_start=None
        # trailing
        if cur_start is not None:
            res.append((cur_start*3+frame, len(s), len(prot)-cur_start, strand, frame))
    return res

